import { createRoute, z } from '@hono/zod-openapi'

const HeaderItemsSchema = z
  .object({ name: z.string().exactOptional(), value: z.string().exactOptional() })
  .openapi({ required: [] })
  .openapi('HeaderItems')

const HMACSignatureSchema = z
  .object({
    headerName: z.string().exactOptional(),
    hmacSecretFormVariableKey: z.string().exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('HMACSignature')

const EndpointSchema = z
  .object({
    headers: z.array(HeaderItemsSchema).exactOptional(),
    hmacSignature: HMACSignatureSchema.exactOptional(),
    method: z.string().exactOptional(),
    url: z.string().exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('Endpoint')

const DynamicOptionFiltersItemsSchema = z
  .object({ attribute: z.string().exactOptional(), variableKey: z.string().exactOptional() })
  .openapi({ required: [] })
  .openapi('DynamicOptionFiltersItems')

const OptionsArraySchema = z
  .object({ label: z.string().exactOptional(), value: z.string().exactOptional() })
  .openapi({ required: [] })
  .openapi('OptionsArray')

const DynamicOptionsParserSchema = z
  .object({
    optionsItems: OptionsArraySchema.exactOptional(),
    optionsPath: z.string().exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('DynamicOptionsParser')

const DynamicOptionsSourceSchema = z
  .object({ key: z.string().exactOptional(), type: z.string().exactOptional() })
  .openapi({ required: [] })
  .openapi('DynamicOptionsSource')

const DynamicOptionsSchema = z
  .object({
    allowUnknownValue: z.boolean().exactOptional(),
    endpoint: EndpointSchema.exactOptional(),
    filters: z.array(DynamicOptionFiltersItemsSchema).exactOptional(),
    parser: DynamicOptionsParserSchema.exactOptional(),
    source: DynamicOptionsSourceSchema.exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('DynamicOptions')

const FormVariableSchema = z
  .object({
    key: z.string().exactOptional(),
    name: z.string().exactOptional(),
    type: z.string().exactOptional(),
    description: z.string().exactOptional(),
    placeholder: z.string().exactOptional(),
    isOptional: z.boolean().exactOptional(),
    defaultValue: z.any().exactOptional(),
    allowedValues: z.array(z.string()).exactOptional(),
    dynamicOptions: DynamicOptionsSchema.exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('FormVariable')

const ApprovalsCapabilityConfigSchema = z
  .object({
    additionalFormVariables: z
      .array(FormVariableSchema)
      .exactOptional()
      .openapi({
        description: 'The additional form variables for the approvals capability',
        example: 'invalid example',
      }),
  })
  .openapi({ required: [] })
  .openapi('ApprovalsCapabilityConfig')

const ActionSpecifierSchema = z.string().openapi('ActionSpecifier')

const StatementPostSchema = z
  .object({
    resources: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description: 'Resource specifier strings',
        example: ['proj/*:env/*:flag/*;testing-tag'],
      }),
    notResources: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'Targeted resources are the resources NOT in this list. The <code>resources</code> field must be empty to use this field.',
      }),
    actions: z
      .array(ActionSpecifierSchema)
      .exactOptional()
      .openapi({ description: 'Actions to perform on a resource', example: ['*'] }),
    notActions: z
      .array(ActionSpecifierSchema)
      .exactOptional()
      .openapi({
        description:
          'Targeted actions are the actions NOT in this list. The <code>actions</code> field must be empty to use this field.',
      }),
    effect: z
      .enum(['allow', 'deny'])
      .openapi({
        description: 'Whether this statement should allow or deny actions on the resources.',
        example: 'allow',
      }),
  })
  .openapi({ required: ['effect'] })
  .openapi('StatementPost')

const StatementPostListSchema = z.array(StatementPostSchema).openapi('StatementPostList')

const AuditLogEventsHookCapabilityConfigPostSchema = z
  .object({
    statements: StatementPostListSchema.exactOptional().openapi({
      description: 'The set of resources you wish to subscribe to audit log notifications for.',
    }),
  })
  .openapi({ required: [] })
  .openapi('AuditLogEventsHookCapabilityConfigPost')

type CapabilityConfigPostType = {
  approvals?: z.infer<typeof ApprovalsCapabilityConfigSchema>
  auditLogEventsHook?: z.infer<typeof AuditLogEventsHookCapabilityConfigPostSchema>
}

const StatementSchema = z
  .object({
    resources: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description: 'Resource specifier strings',
        example: ['proj/*:env/*;qa_*:/flag/*'],
      }),
    notResources: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'Targeted resources are the resources NOT in this list. The <code>resources</code> and <code>notActions</code> fields must be empty to use this field.',
      }),
    actions: z
      .array(ActionSpecifierSchema)
      .exactOptional()
      .openapi({ description: 'Actions to perform on a resource', example: ['*'] }),
    notActions: z
      .array(ActionSpecifierSchema)
      .exactOptional()
      .openapi({
        description:
          'Targeted actions are the actions NOT in this list. The <code>actions</code> and <code>notResources</code> fields must be empty to use this field.',
      }),
    effect: z
      .enum(['allow', 'deny'])
      .openapi({
        description: 'Whether this statement should allow or deny actions on the resources.',
        example: 'allow',
      }),
  })
  .openapi({ required: ['effect'] })
  .openapi('Statement')

const AuditLogEventsHookCapabilityConfigRepSchema = z
  .object({
    statements: z
      .array(StatementSchema)
      .exactOptional()
      .openapi({
        description: 'The set of resources you wish to subscribe to audit log notifications for.',
      }),
  })
  .openapi({ required: [] })
  .openapi('AuditLogEventsHookCapabilityConfigRep')

type CapabilityConfigRepType = {
  approvals?: z.infer<typeof ApprovalsCapabilityConfigSchema>
  auditLogEventsHook?: z.infer<typeof AuditLogEventsHookCapabilityConfigRepSchema>
}

type LinkType = { href?: string; type?: string }

type UnixMillisType = bigint

const DeploymentRepSchema: z.ZodType<DeploymentRepType> = z
  .lazy(() =>
    z
      .object({
        id: z
          .uuid()
          .openapi({
            description: 'The deployment ID',
            example: 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
          }),
        applicationKey: z
          .string()
          .openapi({ description: 'The application key', example: 'billing-service' }),
        applicationVersion: z
          .string()
          .openapi({ description: 'The application version', example: 'a90a8a2' }),
        startedAt: UnixMillisSchema.openapi({
          description: 'The time the deployment started',
          example: '1706701522000',
        }),
        endedAt: UnixMillisSchema.exactOptional().openapi({
          description: 'The time the deployment ended',
          example: '1706712518000',
        }),
        durationMs: z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64(),
          )
          .exactOptional()
          .openapi({
            type: 'integer',
            format: 'int64',
            description: 'The duration of the deployment in milliseconds',
            example: 10996000,
          }),
        status: DeploymentStatusSchema.openapi({
          description: 'The status of the deployment',
          example: 'finished',
        }),
        kind: DeploymentKindSchema.openapi({
          description: 'The kind of deployment',
          example: 'redeployment',
        }),
        active: z
          .boolean()
          .openapi({ description: 'Whether the deployment is active', example: true }),
        metadata: z
          .record(z.string(), z.any())
          .exactOptional()
          .openapi({
            description: 'The metadata associated with the deployment',
            example: { buildNumber: '1234' },
          }),
        archived: z
          .boolean()
          .openapi({ description: 'Whether the deployment is archived', example: false }),
        environmentKey: z
          .string()
          .openapi({ description: 'The environment key', example: 'production' }),
        numberOfContributors: z
          .int()
          .openapi({ description: 'The number of contributors', example: 1 }),
        numberOfPullRequests: z
          .int()
          .openapi({ description: 'The number of pull requests', example: 2 }),
        linesAdded: z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64(),
          )
          .openapi({
            type: 'integer',
            format: 'int64',
            description: 'The number of lines added',
            example: 100,
          }),
        linesDeleted: z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64(),
          )
          .openapi({
            type: 'integer',
            format: 'int64',
            description: 'The number of lines deleted',
            example: 50,
          }),
        leadTime: z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64(),
          )
          .openapi({
            type: 'integer',
            format: 'int64',
            description: 'The total lead time from first commit to deployment end in milliseconds',
            example: 20237000,
          }),
        pullRequests: PullRequestCollectionRepSchema.exactOptional().openapi({
          description: 'The pull requests contained in the deployment',
        }),
        flagReferences: FlagReferenceCollectionRepSchema.exactOptional().openapi({
          description: 'The flag references contained in the deployment',
        }),
        leadTimeStages: LeadTimeStagesRepSchema.exactOptional().openapi({
          description: 'The lead time stages for the deployment',
        }),
      })
      .openapi({
        required: [
          'id',
          'applicationKey',
          'applicationVersion',
          'startedAt',
          'status',
          'kind',
          'active',
          'archived',
          'environmentKey',
          'numberOfContributors',
          'numberOfPullRequests',
          'linesAdded',
          'linesDeleted',
          'leadTime',
        ],
      }),
  )
  .openapi('DeploymentRep')

