const MetricDenominatorRepSchema = z
  .object({
    eventName: z
      .string()
      .exactOptional()
      .openapi({ description: 'The warehouse event column for the denominator' }),
    isNumeric: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'Whether the denominator aggregates a numeric value' }),
    unitAggregationType: z
      .string()
      .exactOptional()
      .openapi({ description: 'How individual unit values are aggregated for the denominator' }),
    unitAggregationField: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The column to count distinct values of; required when unitAggregationType is count_distinct',
      }),
    valueColumn: z
      .string()
      .exactOptional()
      .openapi({ description: 'For a numeric denominator, the column holding the numeric value' }),
    dataSource: MetricDataSourceRefRepSchema.exactOptional().openapi({
      description:
        "The data source for the denominator events. Uses 'launchdarkly-hosted' for SDK-tracked events.",
    }),
    filters: FilterSchema.exactOptional().openapi({
      description: 'Optional filters to narrow which denominator events are included',
    }),
    windowStartOffset: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'Start of the measurement window in milliseconds',
      }),
    windowEndOffset: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'End of the measurement window in milliseconds',
      }),
    winsorLowerPercentile: z
      .number()
      .exactOptional()
      .openapi({ description: 'Lower winsorization percentile in the open interval (0, 100)' }),
    winsorUpperPercentile: z
      .number()
      .exactOptional()
      .openapi({ description: 'Upper winsorization percentile in the open interval (0, 100)' }),
    winsorIncludeImputed: z
      .boolean()
      .exactOptional()
      .openapi({
        description: 'When true, the percentile bound calculation includes imputed zeros',
      }),
  })
  .openapi({ required: [] })
  .openapi('MetricDenominatorRep')

