const MetricPostSchema = z
  .object({
    key: z
      .string()
      .openapi({
        description: 'A unique key to reference the metric',
        example: 'metric-key-123abc',
      }),
    name: z
      .string()
      .exactOptional()
      .openapi({ description: 'A human-friendly name for the metric', example: 'Example metric' }),
    description: z
      .string()
      .exactOptional()
      .openapi({ description: 'Description of the metric', example: 'optional description' }),
    kind: z
      .enum(['pageview', 'click', 'custom', 'trace'])
      .openapi({ description: 'The kind of event your metric will track', example: 'custom' }),
    selector: z
      .string()
      .exactOptional()
      .openapi({
        description: 'One or more CSS selectors. Required for click metrics only.',
        example: '.dropdown-toggle',
      }),
    urls: z
      .array(UrlPostSchema)
      .exactOptional()
      .openapi({
        description: 'One or more target URLs. Required for click and pageview metrics only.',
        example: 'invalid example',
      }),
    isNumeric: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Whether to track numeric changes in value against a baseline (<code>true</code>) or to track a conversion when an end user takes an action (<code>false</code>). Required for custom and trace metrics only.',
        example: false,
      }),
    unit: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The unit of measure. Applicable for numeric custom and trace metrics only.',
        example: 'orders',
      }),
    eventKey: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The event key to use in your code. Required for custom conversion/binary and custom numeric metrics only.',
        example: 'Order placed',
      }),
    successCriteria: z
      .enum(['HigherThanBaseline', 'LowerThanBaseline'])
      .exactOptional()
      .openapi({
        description:
          'Success criteria. Required for custom and trace numeric metrics, optional for custom and trace conversion metrics.',
        example: 'HigherThanBaseline',
      }),
    tags: z
      .array(z.string())
      .exactOptional()
      .openapi({ description: 'Tags for the metric', example: ['example-tag'] }),
    randomizationUnits: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description: 'Deprecated, use <code>analysisUnits</code> instead.',
        example: ['user'],
        deprecated: true,
      }),
    analysisUnits: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description: 'An array of analysis units allowed for this metric.',
        example: ['user'],
      }),
    maintainerId: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The ID of the member who maintains this metric',
        example: '569fdeadbeef1644facecafe',
      }),
    unitAggregationType: z
      .enum(['average', 'sum', 'count_distinct'])
      .exactOptional()
      .openapi({
        description: 'The method by which multiple unit event values are aggregated',
        example: 'average',
      }),
    analysisType: z
      .string()
      .exactOptional()
      .openapi({ description: 'The method for analyzing metric events', example: 'mean' }),
    percentileValue: z
      .int()
      .exactOptional()
      .openapi({
        description:
          'The percentile for the analysis method. An integer denoting the target percentile between 0 and 100. Required when <code>analysisType</code> is <code>percentile</code>.',
        example: 95,
      }),
    eventDefault: MetricEventDefaultRepSchema.exactOptional(),
    dataSource: MetricDataSourceRefRepSchema.exactOptional(),
    filters: EventFilterSchema.exactOptional().openapi({
      description:
        'Filters for the metric to exclude certain events from being included. This is only supported for custom metrics.',
    }),
    windowStartOffset: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description:
          "Not yet implemented - The start of the measurement window, in milliseconds relative to the unit's first exposure to a flag variation",
      }),
    windowEndOffset: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description:
          "Not yet implemented - The end of the measurement window, in milliseconds relative to the unit's first exposure to a flag variation",
      }),
    winsorLowerPercentile: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'Lower winsorization percentile, expressed as a percent in the open interval (0, 100). When both bounds are set, defines a two-sided clamp range. Otherwise lower-only winsorization.',
        example: 1,
      }),
    winsorUpperPercentile: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'Upper winsorization percentile, expressed as a percent in the open interval (0, 100). When both bounds are set, must be greater than winsorLowerPercentile.',
        example: 99.5,
      }),
    winsorIncludeImputed: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          "When true, the percentile bound calculation includes imputed zeros. Only meaningful when at least one bound is set and the metric includes units that didn't send events.",
        example: false,
      }),
    traceQuery: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The trace query to use for the metric. Required for trace metrics.',
        example: 'service.name = "checkout"',
      }),
    traceValueLocation: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The location in the trace to use for numeric values. Required for numeric trace metrics.',
        example: 'duration',
      }),
    unitAggregationField: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The warehouse column to use for counting distinct values. Required when the unitAggregationType is count_distinct.',
      }),
    valueColumn: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'For numeric warehouse-native metrics, the column holding the numeric value. Overrides the value column mapped on the data source.',
      }),
    denominator: DenominatorPostSchema.exactOptional().openapi({
      description:
        'For ratio metrics, the denominator event configuration. Only supported for warehouse native custom metrics.',
    }),
  })
  .openapi({ required: ['key', 'kind'] })
  .openapi('MetricPost')

