const PipelineReleaseGuardianConfigurationInputSchema = z
  .object({
    monitoringWindowMilliseconds: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'The monitoring window in milliseconds',
        example: 60000,
      }),
    rolloutWeight: z
      .int()
      .exactOptional()
      .openapi({ description: 'The rollout weight', example: 50 }),
    rollbackOnRegression: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'Whether or not to rollback on regression', example: true }),
    randomizationUnit: z
      .string()
      .exactOptional()
      .openapi({ description: 'The randomization unit for the measured rollout', example: 'user' }),
  })
  .openapi({ required: [] })
  .openapi('PipelineReleaseGuardianConfigurationInput')

