export const postApiV2FlagsProjectKeyRoute = createRoute({
  method: 'post',
  path: '/api/v2/flags/{projectKey}',
  tags: ['Feature flags'],
  summary: 'Create a feature flag',
  description:
    'Create a feature flag with the given name, key, and variations.\n\n<details>\n<summary>Click to expand instructions for <strong>creating a migration flag</strong></summary>\n\n### Creating a migration flag\n\nWhen you create a migration flag, the variations are pre-determined based on the number of stages in the migration.\n\nTo create a migration flag, omit the `variations` and `defaults` information. Instead, provide a `purpose` of `migration`, and `migrationSettings`. If you create a migration flag with six stages, `contextKind` is required. Otherwise, it should be omitted.\n\nHere\'s an example:\n\n```json\n{\n  "key": "flag-key-123",\n  "purpose": "migration",\n  "migrationSettings": {\n    "stageCount": 6,\n    "contextKind": "account"\n  }\n}\n```\n\nTo learn more, read [Migration Flags](https://launchdarkly.com/docs/home/flags/migration).\n\n</details>\n',
  operationId: 'postFeatureFlag',
  request: {
    params: z.object({
      projectKey: z
        .string()
        .openapi({
          param: {
            name: 'projectKey',
            in: 'path',
            description: 'The project key',
            required: true,
            schema: { type: 'string', format: 'string', description: 'The project key' },
          },
          description: 'The project key',
        }),
    }),
    query: z.object({
      clone: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'clone',
            in: 'query',
            description:
              'The key of the feature flag to be cloned. The key identifies the flag in your code. For example, setting `clone=flagKey` copies the full targeting configuration for all environments, including `on/off` state, from the original flag to the new flag.',
            schema: {
              type: 'string',
              format: 'string',
              description:
                'The key of the feature flag to be cloned. The key identifies the flag in your code. For example, setting `clone=flagKey` copies the full targeting configuration for all environments, including `on/off` state, from the original flag to the new flag.',
            },
            required: false,
          },
          description:
            'The key of the feature flag to be cloned. The key identifies the flag in your code. For example, setting `clone=flagKey` copies the full targeting configuration for all environments, including `on/off` state, from the original flag to the new flag.',
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: FeatureFlagBodySchema,
          example: {
            clientSideAvailability: { usingEnvironmentId: true, usingMobileKey: true },
            key: 'flag-key-123abc',
            name: 'My Flag',
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Global flag response',
      content: { 'application/json': { schema: FeatureFlagSchema } },
    },
    400: {
      description: 'Invalid request',
      content: { 'application/json': { schema: InvalidRequestErrorRepSchema } },
    },
    401: {
      description: 'Invalid access token',
      content: { 'application/json': { schema: UnauthorizedErrorRepSchema } },
    },
    409: {
      description: 'Status conflict',
      content: { 'application/json': { schema: StatusConflictErrorRepSchema } },
    },
    429: {
      description: 'Rate limited',
      content: { 'application/json': { schema: RateLimitedErrorRepSchema } },
    },
  },
})

